import pytest

class SortedAssertion:
    def __call__(self, seq):
        assert all(seq[i] <= seq[i+1] for i in range(len(seq)-1)), 'List is not sorted'

@pytest.fixture
def sorted_assertion():
    return SortedAssertion()

def test_list_is_sorted(sorted_assertion):
    sorted_assertion([1, 2, 2, 5])
    with pytest.raises(AssertionError):
        sorted_assertion([3, 1, 4])
